function streamSession(sessionId2, onEvent, onFinal, onError) {
  const MAX_RECONNECT_ATTEMPTS = 12;
  const MAX_STREAM_DURATION_MS = 12 * 6e4;
  const streamStartedAt = Date.now();
  let lastEventId = null;
  let sseAbort = new AbortController();
  let sseReconnectTimer = null;
  let sseActive = true;
  let onFinalCalled = false;
  let onErrorCalled = false;
  let reconnectAttempts = 0;
  const closeStream = () => {
    if (sseActive) {
      sseActive = false;
      clearTimeout(sseReconnectTimer);
      sseAbort.abort();
    }
  };
  function scheduleReconnect(delayMs = 1500) {
    if (!sseActive || onFinalCalled || onErrorCalled) return;
    reconnectAttempts += 1;
    if (reconnectAttempts > MAX_RECONNECT_ATTEMPTS) {
      closeStream();
      void finalizeFromResult();
      return;
    }
    clearTimeout(sseReconnectTimer);
    sseReconnectTimer = setTimeout(connectSSE, delayMs);
  }
  async function finalizeFromResult() {
    if (onFinalCalled || onErrorCalled) return;
    try {
      const result = await getSessionResult(sessionId2);
      const status = String(result.status || "").toLowerCase();
      const hasDeliverableMemo = Boolean(
        result.memo || result.final?.memo || result.final?.memo_preview || result.memo_event?.preview
      );
      const errorPayload = result.error;
      const errorMessage = typeof errorPayload === "string" ? errorPayload : errorPayload?.message || errorPayload?.payload?.message || null;
      if (errorMessage || result.status === "error") {
        if (!onErrorCalled) {
          onErrorCalled = true;
          onError(new Error(errorMessage || "Research failed"));
        }
        return;
      }
      if (!hasDeliverableMemo && status !== "done") {
        if (!sseActive) {
          if (!onErrorCalled) {
            onErrorCalled = true;
            onError(new Error("Research timed out before a final answer was available."));
          }
          return;
        }
        trackEvent("research_stream_waiting_for_result", {
          source: "frontend",
          session_id: sessionId2,
          status: status || "unknown"
        });
        scheduleReconnect();
        return;
      }
      if (!onFinalCalled) {
        onFinalCalled = true;
        onFinal(result.final || result);
      }
    } catch (err) {
      if (!onErrorCalled) {
        onErrorCalled = true;
        onError(err instanceof Error ? err : new Error("Failed to retrieve session result"));
      }
    }
  }
  function handleTerminalEvent(evType, evData) {
    if (evType === "final") {
      try {
        const parsed = JSON.parse(evData);
        closeStream();
        trackEvent("research_stream_final", {
          source: "frontend",
          session_id: sessionId2
        });
        if (!onFinalCalled) {
          onFinalCalled = true;
          onFinal(parsed);
        }
      } catch (err) {
        console.error("Failed to parse final event data", err);
        void finalizeFromResult();
      }
      return;
    }
    if (evType === "error") {
      try {
        const parsed = JSON.parse(evData);
        closeStream();
        trackEvent("research_stream_error", {
          source: "frontend",
          session_id: sessionId2,
          phase: "stream_error_event",
          message: parsed.message || "unknown"
        });
        if (!onErrorCalled) {
          onErrorCalled = true;
          onError(new Error(parsed.message || "Stream processing error"));
        }
      } catch (err) {
        closeStream();
        trackEvent("research_stream_error", {
          source: "frontend",
          session_id: sessionId2,
          phase: "stream_error_event"
        });
        if (!onErrorCalled) {
          onErrorCalled = true;
          onError(new Error("Stream encountered an error"));
        }
      }
      return;
    }
    if (evType === "done" || evType === "deep_complete") {
      closeStream();
      trackEvent("research_stream_completed", {
        source: "frontend",
        session_id: sessionId2,
        phase: evType
      });
      void finalizeFromResult();
    }
  }
  async function connectSSE() {
    if (!sseActive) return;
    if (Date.now() - streamStartedAt > MAX_STREAM_DURATION_MS) {
      closeStream();
      void finalizeFromResult();
      return;
    }
    sseAbort = new AbortController();
    clearTimeout(sseReconnectTimer);
    sseReconnectTimer = setTimeout(() => {
      if (sseActive) {
        console.info("SSE: proactive reconnect (25s window)");
        sseAbort.abort();
        connectSSE();
      }
    }, 25e3);
    const headers = {
      "Accept": "text/event-stream",
      "Cache-Control": "no-cache"
    };
    const telemetryHeaders = buildTelemetryHeaders(headers);
    const requestId = getTelemetryRequestId(telemetryHeaders) || void 0;
    const token = getAuthToken();
    if (token) {
      telemetryHeaders.set?.("Authorization", `Bearer ${token}`);
    }
    if (lastEventId !== null) {
      telemetryHeaders.set?.("Last-Event-ID", String(lastEventId));
    }
    const path = `/sessions/${encodeURIComponent(sessionId2)}/stream`;
    let url = apiUrl(path);
    if (lastEventId !== null) {
      url += (url.includes("?") ? "&" : "?") + "after=" + encodeURIComponent(lastEventId);
    }
    const startMs = typeof performance !== "undefined" ? performance.now() : Date.now();
    let resp;
    try {
      resp = await fetch(url, {
        headers: withAuthHeaders(telemetryHeaders),
        signal: sseAbort.signal,
        credentials: requestCredentials()
      });
    } catch (err) {
      if (!sseActive) return;
      if (err && err.name === "AbortError") return;
      trackDependency({
        name: `GET ${path}`,
        url,
        method: "GET",
        durationMs: (typeof performance !== "undefined" ? performance.now() : Date.now()) - startMs,
        success: false,
        requestId,
        properties: {
          source: "frontend",
          session_id: sessionId2,
          phase: "stream_connect",
          error_type: err?.name || "Error"
        }
      });
      trackEvent("research_stream_error", {
        source: "frontend",
        session_id: sessionId2,
        phase: "connect"
      });
      console.warn("SSE fetch error, retrying in 2s:", err);
      clearTimeout(sseReconnectTimer);
      sseReconnectTimer = setTimeout(connectSSE, 2e3);
      return;
    }
    trackDependency({
      name: `GET ${path}`,
      url,
      method: "GET",
      durationMs: (typeof performance !== "undefined" ? performance.now() : Date.now()) - startMs,
      success: resp.ok,
      statusCode: resp.status,
      requestId,
      properties: {
        source: "frontend",
        session_id: sessionId2,
        phase: "stream_connect"
      }
    });
    if (!resp.ok) {
      if (!sseActive) return;
      if (resp.status === 404) {
        closeStream();
        void finalizeFromResult();
        return;
      }
      trackEvent("research_stream_error", {
        source: "frontend",
        session_id: sessionId2,
        phase: "http_error",
        status_code: resp.status
      });
      console.warn("SSE HTTP error status:", resp.status, " -  retrying in 3s");
      clearTimeout(sseReconnectTimer);
      sseReconnectTimer = setTimeout(connectSSE, 3e3);
      return;
    }
    trackEvent("research_stream_connected", {
      source: "frontend",
      session_id: sessionId2,
      resumed: String(lastEventId !== null)
    });
    reconnectAttempts = 0;
    const reader = resp.body?.getReader();
    if (!reader) {
      console.error("SSE response body is not readable");
      if (!onErrorCalled) {
        onErrorCalled = true;
        onError(new Error("Response body is not readable"));
      }
      return;
    }
    const decoder = new TextDecoder();
    let buf = "";
    let streamEnded = false;
    try {
      for (; ; ) {
        const { done, value } = await reader.read();
        if (done) {
          streamEnded = true;
          break;
        }
        buf += decoder.decode(value, { stream: true });
        let boundary;
        while ((boundary = buf.indexOf("\n\n")) !== -1) {
          const block = buf.slice(0, boundary);
          buf = buf.slice(boundary + 2);
          if (!block.trim() || block.startsWith(":")) continue;
          let evType = "message";
          let evData = "";
          let evId = null;
          for (const line of block.split("\n")) {
            if (line.startsWith("event:")) {
              evType = line.slice(6).trim();
            } else if (line.startsWith("data:")) {
              evData = line.slice(5).trim();
            } else if (line.startsWith("id:")) {
              evId = line.slice(3).trim();
            }
          }
          if (evId !== null) {
            const parsedId = parseInt(evId, 10);
            if (!isNaN(parsedId)) {
              lastEventId = parsedId;
            }
          }
          if (evType === "final" || evType === "error" || evType === "done" || evType === "deep_complete") {
            handleTerminalEvent(evType, evData);
            continue;
          }
          try {
            const parsed = JSON.parse(evData);
            onEvent({
              seq: parsed.id || (evId ? parseInt(evId, 10) : 0),
              type: evType,
              timestamp: parsed.timestamp || "",
              payload: parsed
            });
          } catch (err) {
            console.error(`Failed to parse ${evType} event data`, err);
          }
        }
      }
      if (sseActive && !onFinalCalled && !onErrorCalled) {
        scheduleReconnect(1e3);
      }
    } catch (err) {
      if (!sseActive) return;
      if (err && err.name === "AbortError") return;
      console.warn("SSE read error, retrying in 2s:", err);
      clearTimeout(sseReconnectTimer);
      sseReconnectTimer = setTimeout(connectSSE, 2e3);
      return;
    }
    if (streamEnded && sseActive && !onFinalCalled && !onErrorCalled) {
      void finalizeFromResult();
    }
  }
  connectSSE();
  return () => {
    closeStream();
  };
}
